// src/plugin/context.ts
async function sessionContext(cwd, dataFolder2, session) {
  let repository;
  try {
    repository = await RepositoryGoals.of(dataFolder2, cwd);
  } catch (error62) {
    if (error62 instanceof GitError) return void 0;
    throw error62;
  }
  const goals = await repository.list();
  const mine = goals.find((g) => g.holder?.session === session);
  const parts = [];
  if (mine && "state" in mine) {
    const status = statusText(await repository.stored(mine.slug, mine.state));
    parts.push(
      `This session runs cc-huddle's goal "${mine.state.goal.name}", as it stands:

${status}`
    );
  }
  const others = othersText(goals.filter((g) => g !== mine && takeable(g)));
  if (others) parts.push(`cc-huddle: ${others}`);
  return parts.length ? parts.join("\n\n") : void 0;
}

